"use client";
/* Para, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Para(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("para"); }, []);
  return React.createElement("piix-pal", { "pal": "para", ...piixAttrs(props) });
}

export default Para;
